1	import React from 'react';
2	import {useCurrentFrame,useVideoConfig} from 'remotion';
3	import {FONT,widthOf} from '../../../lib/type';
4	import {useArtDirection} from '../../../lib/artDirection';
5	import {actionProgress,actionWindows,requireAction,requireNarration,type DirectedScene} from '../../../lib/direction';
6	import {PlaceSubject} from '../../PlaceStage';
7	import {LOCATOR_START_S,LOCATOR_END_S} from '../../CountyLocator';
8	import type {FilmRenderProps} from '../../types';
9	import {FloodStationHero,STATION,podPoint,type Pal,type Pt} from './FloodStationHero';
10	import {StreetHubSupport,PORCH} from './StreetHubSupport';
11	
12	/**
13	 * flood-station-v1: UT San Antonio's solar flood station, as the university describes the design.
14	 *
15	 * ONE station and ONE rising waterline carry the film. The water reaches the station's lowest
16	 * optical mark at ankle height in the opening, crosses the second mark in the sensing scene and the
17	 * third in the close, and every mark it has crossed stays lit. The battery bar the sun fills, the
18	 * weather lamps and the amber risk lamp the chip lights all stay in their new state for the rest of
19	 * the film, so each later shot of the station carries what earlier shots performed.
20	 *
21	 * A: the yard-first treatment. Water creeps across a San Antonio yard past the orange ankle mark on a
22	 *    chain link post while the phone on the porch rail stays dark, and the warning lights it late.
23	 *    Then the station at the curb is found, charged, climbed, wetted, opened to its chip, followed by
24	 *    its radio pulse down the street to the hub, read on the hub's map, measured on its two cards,
25	 *    and left by the street with a dashed goal pin over the empty map on the fence.
26	 * B: the instrument-first treatment. It opens in the water at the post, where the lowest optical mark
27	 *    goes under and lights, and only then pulls back to the yard and the late phone. It reads the
28	 *    battery before the station, the weather lamps before the water marks, the empty server before
29	 *    the chip, the radio from above before the street, the hub map before the desk and the blank
30	 *    field card before the validation card, and it ends on the paper map with the station small at
31	 *    its corner and the dashed goal pin that has not landed.
32	 *
33	 * Every visible state is a function of the film frame clock and the board's event windows; nothing
34	 * accumulates between frames. The Bexar County plate stands behind every exterior shot and the hub's
35	 * window; this episode never paints a full-frame background. Card, map and dashboard views are wall
36	 * views in the registry. Disclosed illustration: no installed station, real street, hub, dashboard,
37	 * responder, deployment or field result.
38	 */
39	
40	type V='a'|'b';
41	const clamp=(v:number)=>Math.min(1,Math.max(0,v));
42	const lerp=(a:number,b:number,p:number)=>a+(b-a)*p;
43	const ease=(p:number)=>{const q=clamp(p);return q*q*q*(10+q*(-15+6*q));};
44	const mix=(a:Pt,b:Pt,p:number):Pt=>[lerp(a[0],b[0],p),lerp(a[1],b[1],p)];
45	
46	/** The university's reported figure, verbatim from claim c4's quote, and the bar share it sets. */
47	const VALIDATION={text:'98.82%',share:.9882};
48	/** The water level, in station units, that each part of the story leaves behind. The lowest mark
49	 * sits at ankle height; the level only rises. */
50	const LEVEL={start:-26,ankle:-66,second:-150};
51	/** Pod lamp from the water level: a mark lights as the water reaches it and stays lit. */
52	const podLit=(level:number,i:number)=>clamp((STATION.pods[i]-level)/16+.35);
53	const DISCLOSURE_FONT=26, DISCLOSURE_MAX=330;
54	function disclosureLines(text:string):string[]{
55	 const words=text.split(' '), lines:string[]=[];let cur='';
56	 for(const w of words){const next=cur?cur+' '+w:w;if(cur&&widthOf(next,DISCLOSURE_FONT,true)>DISCLOSURE_MAX){lines.push(cur);cur=w;}else cur=next;}
57	 if(cur)lines.push(cur);return lines;
58	}
59	
60	const At:React.FC<{p:Pt;s?:number;r?:number;o?:number;children:React.ReactNode}>=({p,s=1,r=0,o=1,children})=>
61	 <g transform={`translate(${p[0]} ${p[1]}) rotate(${r}) scale(${s})`} opacity={o}>{children}</g>;
62	/** A camera: world point f lands on screen point a at scale s. */
63	const Cam:React.FC<{f:Pt;s:number;a?:Pt;children:React.ReactNode}>=({f,s,a=[540,820],children})=>
64	 <g transform={`translate(${a[0]} ${a[1]}) scale(${s}) translate(${-f[0]} ${-f[1]})`}>{children}</g>;
65	/** A subject standing on the region's ground outdoors rides the plate's camera with its base row. */
66	const Grounded:React.FC<{baseY:number;on:boolean;children:React.ReactNode}>=({baseY,on,children})=>
67	 on?<PlaceSubject baseY={baseY}>{children}</PlaceSubject>:<g>{children}</g>;
68	/** Name the drawn group with its board item id, so the board binds what is actually rendered. */
69	const Item:React.FC<{id:string;children:React.ReactNode}>=({id,children})=><g data-item={id}>{children}</g>;
70	
71	export const FloodStationFilm:React.FC<FilmRenderProps>=({board,scene,shot,time_s,variant})=>{
72	 const ad=useArtDirection();if(!ad)throw new Error('Flood station film requires the executed art direction profile');
73	 const frame=useCurrentFrame(),{fps}=useVideoConfig(),t=frame/fps;
74	 if(Math.abs(t-time_s)>1e-6)throw new Error('Flood station film must read the single film frame clock');
75	 const pal:Pal=ad.palette, v:V=variant;
76	 const W=actionWindows(board.scenes as unknown as DirectedScene[]);
77	 const win=(id:string)=>requireAction(W,id);
78	 const p=(id:string)=>actionProgress(win(id),t);
79	 /** A treatment-only event: absent in the other treatment, where its view never draws it. */
80	 const pOpt=(id:string,fallback=1)=>W[id]?actionProgress(W[id],t):fallback;
81	 const raw=(w:{start:number;end:number})=>clamp((t-w.start)/(w.end-w.start));
82	 const clause=board.narration_picture!.clauses.find(r=>t>=r.start_s&&t<r.end_s);
83	 const act=clause?.action_id??(shot as typeof shot&{narration_ids?:string[]}).narration_ids?.map(id=>requireNarration(board,id).actionId)[0]??'hold';
84	 const sid=scene.id, at=(s:string)=>sid===s;
85	 const flat=ad.flat_shots?.[sid];
86	 const fr=shot.framing, view=shot.view;
87	 const st=t-scene.start_s;
88	 const exterior=!scene.interior&&fr!=='overhead';
89	
90	 // ---- the performed states, each read from its own event on the film clock ----
91	 const s1e1=p('s1-event-1'), s1e2=p('s1-event-2'), s1e3=p('s1-event-3'), s1e0=pOpt('s1-event-0');
92	 const s2e1=p('s2-event-1'), s2e2=p('s2-event-2'), s2e3=p('s2-event-3');
93	 const s3e1=p('s3-event-1'), s3e2=p('s3-event-2'), s3e3=p('s3-event-3');
94	 const s4e1=p('s4-event-1'), s4e2=p('s4-event-2'), s4e3=p('s4-event-3');
95	 const s5e1=p('s5-event-1'), s5e2=p('s5-event-2'), s5e3=p('s5-event-3');
96	 const s6e1=p('s6-event-1'), s6e2=p('s6-event-2'), s6e3=p('s6-event-3');
97	 const s7e1=p('s7-event-1'), s7e2=p('s7-event-2'), s7e3=p('s7-event-3');
98	 const s8e1=p('s8-event-1'), s8e2=p('s8-event-2'), s8e3=p('s8-event-3');
99	 const s9e1=p('s9-event-1'), s9e2=p('s9-event-2'), s9e3=p('s9-event-3');
100	
101	 // ---- the station's carried state. The water only rises and nothing it has done is undone. ----
102	 // B's s1 design detail: the lowest, ankle-height lens goes under on s1-event-0 (no station stands in
103	 // the s1 yard in either treatment). s2: the prototype stands in ankle-deep water. s3: the second mark
104	 // goes under on s3-event-2. The close draws no station measuring anything: it is an outline.
105	 const level=at('s1')?lerp(LEVEL.start,LEVEL.ankle,ease(s1e0))-4*clamp(st/scene.duration_s)
106	  :at('s2')?LEVEL.ankle
107	  :at('s3')?lerp(LEVEL.ankle,LEVEL.second,s3e2)
108	  :LEVEL.second;
109	 const pods=[0,1,2,3].map(i=>podLit(level,i));
110	 const battery=at('s1')?.24:at('s2')?lerp(.24,1,s2e2):1;
111	 const weather=[0,1,2,3].map(k=>at('s1')||at('s2')?0:at('s3')?clamp(s3e3*4.2-k*1.05):1);
112	 const risk=['s1','s2','s3'].includes(sid)?0:at('s4')?s4e2:1;
113	 const station=(o:Partial<{pods:number[];battery:number;sun:number;sunStrength:number;risk:number;weather:number[];transmit:number;window:number;readings:number;wetTo:number;shadow:number}>={})=>
114	  <FloodStationHero part="station" pods={pods} battery={battery} risk={risk} weather={weather} wetTo={level} time={t} {...o}/>;
115	 const tag=(lines:string[],shown:number,o:{tone?:'ink'|'accent'|'paper'|'outline';side?:'left'|'right';scale?:number;drop?:number;size?:number}={})=>
116	  shown<=0?null:<g transform={`translate(0 ${-40*(o.scale??1)*(1-ease(shown))})`} opacity={clamp(shown*3)}>
117	   <FloodStationHero part="tag" lines={lines} pal={pal} tone={o.tone} side={o.side} scale={o.scale} drop={o.drop} size={o.size}
118	    swing={10*(1-ease(shown))*(o.side==='left'?1:-1)}/></g>;
119	
120	 // ---- the disclosure chip; it names the county map only while the locator card is on screen ----
121	 const sceneList=board.scenes as unknown as {id:string;production_disclosure?:string}[];
122	 const namesMap=(d?:string)=>/\bMap\b/.test(d??'');
123	 const mapShown=t>LOCATOR_START_S&&t<LOCATOR_END_S;
124	 const plain=sceneList.find(s=>s.production_disclosure&&!namesMap(s.production_disclosure))?.production_disclosure??'Illustration';
125	 const mapped=sceneList.find(s=>namesMap(s.production_disclosure))?.production_disclosure;
126	 const own=scene.production_disclosure??'Illustration';
127	 const disclosureText=mapShown&&mapped?mapped:namesMap(own)?plain:own;
128	 const dLines=disclosureLines(disclosureText);
129	 const dW=Math.max(...dLines.map(l=>widthOf(l,DISCLOSURE_FONT,true)))+34, dH=dLines.length*32+24;
130	 const disclosure=<g data-disclosure="production_disclosure">
131	  <rect x={44} y={132} width={dW} height={dH} rx={16} fill={pal.paper} opacity={.93}/>
132	  {dLines.map((l,i)=><text key={i} x={60} y={164+i*32} fontFamily={FONT.body} fontSize={DISCLOSURE_FONT} fontWeight={700} fill={pal.ink}>{l}</text>)}
133	 </g>;
134	
135	 // ---- the curbside world: far verge, a flooded street, the limestone curb and the yard ----
136	 type Curbside={curbY:number;streetTop:number;water?:{front:number;street?:boolean};rain?:number;grounded:boolean};
137	 const curbside=(o:Curbside)=>{
138	  const g=o.grounded;
139	  return <g data-world="curbside">
140	   <Grounded baseY={o.curbY+40} on={g}>
141	    <rect x={-60} y={o.streetTop-18} width={1200} height={22} fill="#8D9358"/>
142	    <StreetHubSupport part="street" x0={-60} x1={1140} yFar={o.streetTop} yNear={o.curbY} t={t}/>
143	    {o.water?.street!==false&&o.water&&<StreetHubSupport part="water" x0={-60} x1={1140} y={o.streetTop+4} depth={o.curbY-o.streetTop-2} t={t} edge="straight" opacity={.8}/>}
144	    <StreetHubSupport part="curb" x0={-60} y0={o.curbY} x1={1140} y1={o.curbY-6} h={20}/>
145	    <StreetHubSupport part="lawn" d={`M-60 ${o.curbY+20}L1140 ${o.curbY+14}L1140 1980L-60 1980Z`} box={[-60,o.curbY+14,1200,1980-o.curbY]}/>
146	    {o.water&&<StreetHubSupport part="water" x0={-60} x1={1140} y={o.curbY+6} depth={Math.max(8,o.water.front-o.curbY)} t={t} seed={13}/>}
147	   </Grounded>
148	  </g>;
149	 };
150	 const rain=(op=.3)=><StreetHubSupport part="rain" t={t} w={1240} h={1920} opacity={op}/>;
151	 /** A ring of light ripple where a grounded thing stands in water, depth px above its base. */
152	 const waterline=(x:number,base:number,w:number,depth:number)=>depth>0&&<g data-part="waterline">
153	  {[0,1].map(k=>{const ph=((t*.8+k*.5)%1);return <ellipse key={k} cx={x} cy={base-depth} rx={w*(1+ph*.9)} ry={w*(1+ph*.9)*.2} fill="none" stroke="#EFE4CC" strokeWidth={2.6} opacity={.85*(1-ph)}/>;})}
154	  <ellipse cx={x} cy={base-depth} rx={w} ry={w*.2} fill="none" stroke="#F6EEDC" strokeWidth={3} opacity={.9}/></g>;
155	
156	 let pic:React.ReactNode;
157	 switch(view){
158	 case 'street-yard':{
159	  // s1 wide: the university's general example, a San Antonio yard with NO station in it. Water from
160	  // the flooded street tops the limestone curb and spreads across the yard; on the chain link post the
161	  // waterline climbs to its orange ankle mark and reaches the rain boots on the porch step while the
162	  // phone on the porch rail stays dark. A holds and pushes in slowly on the post. B arrives on a match
163	  // cut from the design detail's ankle-height lens to the post's ankle mark at the same screen spot,
164	  // then pulls back to the whole yard.
165	  const spread=s1e1;
166	  const front=lerp(1150,1300,ease(spread))+lerp(0,74,s1e2);
167	  const fence:Pt=[600,1300], fs=1.5, post:Pt=[fence[0]+175*fs,fence[1]];
168	  const markDepth=lerp(0,30,ease(spread))*fs+lerp(0,6,s1e2);
169	  const porch:Pt=[-30,1400], rail:Pt=[porch[0]+PORCH.railTop[0],porch[1]+PORCH.railTop[1]];
170	  const boots:Pt=[porch[0]+PORCH.w*.56,porch[1]-34];
171	  const bootDepth=clamp((front-1330)/40)*22;
172	  const world=<g>
173	   <Item id="s1-water">{curbside({curbY:1102,streetTop:1046,water:{front},grounded:exterior})}</Item>
174	   <Grounded baseY={1196} on={exterior}><At p={[1000,1196]}><StreetHubSupport part="oak" h={640} seed={9} flip/></At></Grounded>
175	   <Grounded baseY={fence[1]} on={exterior}><Item id="s1-post"><At p={fence} s={fs}><StreetHubSupport part="fence" x0={0} x1={350} h={300} posts={3} mark={1}/></At>
176	    {waterline(post[0],post[1],22,markDepth)}</Item></Grounded>
177	   <Grounded baseY={porch[1]} on={exterior}><At p={porch}><StreetHubSupport part="porch"/></At>
178	    <Item id="s1-boots"><At p={boots}><StreetHubSupport part="boots"/></At>{waterline(boots[0]+60,boots[1],70,bootDepth)}</Item>
179	    <Item id="s1-phone"><At p={[rail[0]+60,rail[1]-10]}><g transform="scale(.3 .11) rotate(90)"><StreetHubSupport part="phone" pal={pal} banner={0} t={t}/></g></At></Item></Grounded>
180	   {rain(.28)}
181	  </g>;
182	  if(v==='a'){
183	   const push=ease(raw({start:shot.start_s,end:shot.start_s+shot.duration_s}));
184	   pic=<Cam f={mix([540,980],[660,1060],push)} s={lerp(1,1.08,push)} a={mix([540,980],[600,1020],push)}>{world}</Cam>;
185	  }else{
186	   const e=ease(raw({start:shot.start_s,end:win('s1-event-1').end}));
187	   pic=<Cam f={mix([post[0],post[1]-39],[540,1000],e)} s={lerp(2.2,1,e)} a={mix([540,1154],[540,1000],e)}>{world}</Cam>;
188	  }
189	  break;}
190	 case 'phone-late':{
191	  // s1 close, looking down at the porch rail's wide cap board. The worn phone lies on it, dark, the
192	  // flood below the balusters; the warning banner slides in only now, after the water is in the yard.
193	  const rot=v==='a'?-10:8, at0:Pt=v==='a'?[540,950]:[560,960];
194	  pic=<g data-world="porch-rail">
195	   <Item id="s1-water"><StreetHubSupport part="water" x0={-60} x1={1140} y={1300} depth={660} t={t} edge="straight"/></Item>
196	   {Array.from({length:6},(_,i)=><rect key={i} x={40+i*180+(v==='a'?0:60)} y={1280} width={34} height={420} fill="#EDE6D6" stroke="#BDB2A0" strokeWidth={2}/>)}
197	   <path d="M-40 700L1120 676L1120 1222L-40 1252Z" fill="#F3EEE3" stroke="#BDB2A0" strokeWidth={3}/>
198	   <path d="M-40 1252L1120 1222L1120 1282L-40 1314Z" fill="#D5CBB8"/>
199	   {[[150,780],[760,1170],[930,760],[300,1200]].map(([x,y],i)=><ellipse key={i} cx={x} cy={y} rx={30+i*8} ry={4} fill="#B8AD98" opacity={.6}/>)}
200	   <path d="M-40 708L1120 684" stroke="#FFFFFF" strokeWidth={3} opacity={.6}/>
201	   <Item id="s1-phone"><At p={at0} s={1.5} r={rot}><g transform="scale(1 .85)">
202	    <Item id="s1-banner"><StreetHubSupport part="phone" pal={pal} banner={s1e3} t={t}/></Item></g></At></Item>
203	   {rain(.22)}
204	  </g>;
205	  break;}
206	 case 'station-wide':{
207	  // s2 wide: the whole prototype station at the curb, standing in shallow water with its lowest mark
208	  // lit, revealed on s2-event-1 while "its researchers built a flood station" is heard. A tilts up from
209	  // the wet foot; B cranes down from the antenna tip to the whole station.
210	  const base:Pt=[500,1380], s=.86;
211	  const world=<g>
212	   {curbside({curbY:1240,streetTop:1110,water:{front:1430},grounded:exterior})}
213	   <Grounded baseY={base[1]} on={exterior}><Item id="s2-station"><Item id="s2-post"><Item id="s2-panel"><At p={base} s={s}>{station({})}</At></Item></Item></Item>
214	    {waterline(base[0]+8,base[1],34,-LEVEL.ankle*s)}
215	    <At p={[base[0]+130,base[1]-860]}>{tag(['Prototype','flood station'],s2e1,{side:'right',drop:30,scale:.9})}</At></Grounded>
216	   {rain(.2)}
217	  </g>;
218	  const e=ease(raw({start:shot.start_s,end:win('s2-event-1').end}));
219	  pic=v==='a'
220	   ?<Cam f={mix([base[0],base[1]-140],[540,860],e)} s={lerp(1.7,1,e)} a={mix([540,1100],[540,860],e)}>{world}</Cam>
221	   :<Cam f={mix([base[0]+80*s,base[1]-1080*s],[540,860],e)} s={lerp(2.0,1,e)} a={mix([560,560],[540,860],e)}>{world}</Cam>;
222	  break;}
223	 case 'panel-charge':{
224	  // s2 close. Low sun from the upper left reaches the small panel, a glint crosses its cells and the
225	  // battery bar fills cell by cell on s2-event-2 ("that charges itself from light"). B holds this close
226	  // through "and needs no cell tower": a far cell tower stands on the horizon behind the antenna and a
227	  // dashed line toward it stops halfway on s2-event-3.
228	  const s=v==='a'?1.6:1.85, base:Pt=v==='a'?[560,2560]:[600,2830];
229	  const sun=s2e2, beam=clamp(s2e2*3)*(1-.4*clamp((s2e2-.8)*5));
230	  const tip:Pt=[base[0]+110*s,base[1]-1146*s], towerAt:Pt=[985,1036], towerTop:Pt=[985,1036-460*.5];
231	  const end=mix(tip,towerTop,lerp(0,.5,ease(s2e3)));
232	  pic=<g data-world="panel-close">
233	   {v==='b'&&<Item id="s2-tower"><At p={towerAt} s={.5}><StreetHubSupport part="tower" h={420} dim={.25}/></At></Item>}
234	   <path d={`M-200 -200L${base[0]-28*s-200} ${base[1]-1062*s-120}L${base[0]-28*s+120} ${base[1]-1062*s+60}Z`} fill="#FFE2B6" opacity={.28*beam}/>
235	   <path d={`M-200 -200L${base[0]-28*s-120} ${base[1]-1062*s-40}`} stroke="#FFF1D8" strokeWidth={6} opacity={.35*beam}/>
236	   <Item id="s2-station"><At p={base} s={s}><Item id="s2-panel"><Item id="s2-battery">{station({sun,sunStrength:beam,shadow:0})}</Item></Item></At></Item>
237	   <At p={[120,560]}>{tag(['Charges from light'],s2e2,{side:'right',drop:24,scale:.85})}</At>
238	   {v==='b'&&s2e3>0&&<g data-part="unconnected-link"><path d={`M${tip[0]} ${tip[1]}L${end[0]} ${end[1]}`} stroke={pal.ink} strokeWidth={6} strokeDasharray="16 12" strokeLinecap="round"/>
239	    <circle cx={end[0]} cy={end[1]} r={13} fill="none" stroke={pal.ink} strokeWidth={5}/></g>}
240	   {v==='b'&&<At p={[1040,520]}>{tag(['No cell tower','needed'],s2e3,{side:'left',drop:24,scale:.8})}</At>}
241	   {rain(.12)}
242	  </g>;
243	  break;}
244	 case 'no-tower':{
245	  // A s2 third shot. The station in the left foreground, a far cell tower on the horizon; a dashed
246	  // line leaves the antenna toward the tower and stops halfway with an open ring.
247	  const base:Pt=[300,1400], s=.9;
248	  const from:Pt=[base[0]+110*s,base[1]-1146*s], to:Pt=[820,1050-450*.8];
249	  const stop=lerp(0,.5,ease(s2e3)), end=mix(from,to,stop);
250	  pic=<g data-world="curbside-tower">
251	   {curbside({curbY:1210,streetTop:1090,water:{front:1430},grounded:exterior})}
252	   <Grounded baseY={1050} on={exterior}><Item id="s2-tower"><At p={[820,1050]} s={.8}><StreetHubSupport part="tower" h={420} dim={.25}/></At></Item></Grounded>
253	   <Grounded baseY={base[1]} on={exterior}><Item id="s2-station"><At p={base} s={s}><Item id="s2-panel">{station({})}</Item></At></Item></Grounded>
254	   {s2e3>0&&<g data-part="unconnected-link"><path d={`M${from[0]} ${from[1]}L${end[0]} ${end[1]}`} stroke={pal.ink} strokeWidth={6} strokeDasharray="18 13" strokeLinecap="round"/>
255	    <circle cx={end[0]} cy={end[1]} r={15} fill="none" stroke={pal.ink} strokeWidth={6}/></g>}
256	   <At p={[780,760]}>{tag(['No cell tower','needed'],s2e3,{side:'left',drop:28,scale:.95})}</At>
257	   {rain(.2)}
258	  </g>;
259	  break;}
260	 case 'sensor-stack':{
261	  // A s3 medium. The view climbs the post from the wet foot past four optical marks at four
262	  // different heights; each lens catches the low light as the view passes it on s3-event-1.
263	  const base:Pt=[520,1400], s=1.9;
264	  const climb=ease(s3e1);
265	  const glints=[0,1,2,3].map(i=>Math.sin(Math.PI*clamp(s3e1*4-i)));
