502	   {[[card[0]+12,card[1]+6],[card[0]+cw-14,card[1]+8]].map(([x,y],i)=><circle key={i} cx={x} cy={y} r={7} fill="#5A5249"/>)}
503	   {close&&<Item id="s9-station"><Grounded baseY={1400} on={exterior}><At p={[360,1400]} s={.84}><FloodStationHero part="outline" p={s9e2} pal={pal}/></At></Grounded></Item>}
504	   <Item id={sx==='s8'?'s8-tag':'s9-notown'}><At p={[950,640]}>{tag(['No installation','named'],noTown,{side:'left',drop:20,scale:.8,tone:'ink'})}</At></Item>
505	   {close&&<Item id="s9-tag"><At p={[560,500]}>{tag(['Deployment goal'],s9e3,{side:'right',drop:24,scale:.85,tone:'accent'})}</At></Item>}
506	  </g>;
507	  break;}
508	 default:throw new Error('Unimplemented flood station view '+view);
509	 }
510	 return <svg width="1080" height="1920" viewBox="0 0 1080 1920" style={{position:'absolute',inset:0}}>
511	  <g data-view={view} data-framing={fr} data-clause={clause?.id} data-action={act} data-variant={v}
512	   transform={`translate(${flat?.x??0} ${flat?.y??0}) scale(${flat?.scale??1})`}>{pic}</g>
513	  {disclosure}
514	 </svg>;
515	};
516	/** Layout constants, exported for readers of the geometry above. */
517	export const FLOOD_STATION_LAYOUT={LEVEL,VALIDATION,STATION};
